interface ComparableTemp { int compareTo(Object other); }
class Temperature implements ComparableTemp {
    double value;
    Temperature(double v) { value = v; }
    public int compareTo(Object other) { return Double.compare(value, ((Temperature) other).value); }
}

public static void main(String[] args) {
    Temperature[] temps = { new Temperature(20), new Temperature(35), new Temperature(15) };
    Temperature max = temps[0];
    for (Temperature t : temps) if (t.compareTo(max) > 0) max = t;
    System.out.println(max.value);
}

