interface SortStrategy { void sort(int[] arr); }
class Sorter { void run(SortStrategy s, int[] arr) { s.sort(arr); } }

public static void main(String[] args) {
    SortStrategy reverseSort = arr -> { for (int i = 0; i < arr.length / 2; i++) { int t = arr[i]; arr[i] = arr[arr.length-1-i]; arr[arr.length-1-i] = t; } };
    int[] data = {1,2,3,4,5};
    new Sorter().run(reverseSort, data);
    System.out.println(java.util.Arrays.toString(data));
}

interface Predicate2<T> { boolean test(T value); }

static <T> java.util.List<T> filter(T[] arr, Predicate2<T> pred) {
    java.util.List<T> result = new java.util.ArrayList<>();
    for (T t : arr) if (pred.test(t)) result.add(t);
    return result;
}

public static void main(String[] args) {
    Integer[] nums = {1, -2, 3, -4, 5};
    System.out.println(filter(nums, n -> n > 0));
}

