interface EventListener<T> { void onEvent(T event); }
class LoginEvent { String userId; LoginEvent(String id) { userId = id; } }
class EventBus {
    java.util.Map<Class<?>, EventListener> listeners = new java.util.HashMap<>();
    <T> void subscribe(Class<T> type, EventListener<T> listener) { listeners.put(type, listener); }
    @SuppressWarnings("unchecked")
    <T> void emit(T event) { EventListener l = listeners.get(event.getClass()); if (l != null) l.onEvent(event); }
}

public static void main(String[] args) {
    EventBus bus = new EventBus();
    bus.subscribe(LoginEvent.class, (LoginEvent e) -> System.out.println("Zalogowano: " + e.userId));
    bus.emit(new LoginEvent("user1"));
}

