interface Condition {
    boolean evaluate(int n);
    default Condition and(Condition other) { return n -> this.evaluate(n) && other.evaluate(n); }
    default Condition or(Condition other) { return n -> this.evaluate(n) || other.evaluate(n); }
}

public static void main(String[] args) {
    Condition positive = n -> n > 0;
    Condition even = n -> n % 2 == 0;
    Condition divisibleBy3 = n -> n % 3 == 0;
    Condition combined = positive.and(even).or(divisibleBy3);
    System.out.println(combined.evaluate(4) + " " + combined.evaluate(-3));
}

