interface Observer<T> { void update(T value); }
class Observable<T> {
    java.util.List<Observer<T>> observers = new java.util.ArrayList<>();
    void subscribe(Observer<T> o) { observers.add(o); }
    void setValue(T value) { for (Observer<T> o : observers) o.update(value); }
}

public static void main(String[] args) {
    Observable<Integer> counter = new Observable<>();
    counter.subscribe(v -> System.out.println("Obserwator 1: " + v));
    counter.setValue(5);
}

