interface Repository<T, ID> {
    void save(T entity); T findById(ID id); void delete(ID id);
    default void saveAll(T[] entities) { for (T e : entities) save(e); }
}
class InMemoryUserRepository implements Repository<String, Integer> {
    java.util.Map<Integer, String> data = new java.util.HashMap<>();
    public void save(String entity) { data.put(data.size(), entity); }
    public String findById(Integer id) { return data.get(id); }
    public void delete(Integer id) { data.remove(id); }
}

public static void main(String[] args) {
    new InMemoryUserRepository().saveAll(new String[]{"Ala", "Bartek"});
}

interface Specification<T> {
    boolean isSatisfiedBy(T item);
