interface MessageSender { void send(String to, String msg); }
class EmailSender implements MessageSender { public void send(String to, String msg) { System.out.println("Email do " + to + ": " + msg); } }
class SmsSender implements MessageSender { public void send(String to, String msg) { System.out.println("SMS do " + to + ": " + msg); } }
class NotificationService {
    MessageSender[] senders;
    NotificationService(MessageSender[] senders) { this.senders = senders; }
    void notifyAll(String to, String msg) { for (MessageSender s : senders) s.send(to, msg); }
}

public static void main(String[] args) {
    NotificationService service = new NotificationService(new MessageSender[]{ new EmailSender(), new SmsSender() });
    service.notifyAll("user@example.com", "Witaj!");
    // Dodanie PushSender wymaga TYLKO nowej klasy implementujacej MessageSender - ZERO zmian w NotificationService,
